using System;
using System.Collections.Immutable;
using System.Linq;
using Extensions.Pack;
using AspNetCore.MinimalApi.Sdk.CodeRules.Mediator;
using Solution.Parser.CSharp;

namespace AspNetCore.MinimalApi.Sdk.CodeRules
{
    [TestCategory("Coding-Rules")]
    [TestCategory("Mediator")]
    [TestClass]
    public class RJIT_CR_M_00007 : MediatorTestBase
    {
        [TestMethod]
        public void Handler_Have_To_Be_Internal()
        {
            var publicHandlers = (from implementation in MediatorImplementations
                                  where implementation.Handler.Modifiers.Any(m => m == Modifier.Public)
                                  select new
                                  {
                                      Error = $@"
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Class:      {implementation.Handler.FullQualifiedName}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Current:    

{implementation.Handler.SyntaxTree.FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Should be:  

{implementation.Handler.SyntaxTree.Replace("public", "internal").FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
"
                                  }).ToImmutableList();


            Assert.IsTrue(publicHandlers.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_MR_00007

Your MediatR handlers have not to be public. A request handler is an implementation detail and should not be exposed to the outside world.

Found:{publicHandlers.Count}

{publicHandlers.Select(e => e.Error).Flatten(Environment.NewLine)}");
        }
    }
